  and co.order_no = #{orderNo}
  and co.customer_code = #{customerCode}

select * from customer_order co
where co.is_delete = 0
  and co.order_no = #{orderNo}
  and co.customer_code = #{customerCode}
for update

select * from customer_order co
where co.is_delete = 0
  and co.tenant_code = #{tenantCode}
  and co.customer_code = #{customerCode}
  and co.sub_mode = #{subMode}
  and co.status = #{status}

select * from customer_order co
where co.order_time <= #{orderTime}
and co.status = #{paymentStatus}

  and co.sub_mode = #{subMode}


  and co.customer_code = #{customerCode}

and co.is_delete = 0
order by co.order_time asc, co.id asc
limit #{limit}

select * from customer_order co
where co.tenant_code = #{tenantCode}
  and co.application_no = #{applicationNo}
  and co.sub_type = #{subType}
  and co.is_delete = 0

select * from customer_order co
where co.is_delete = 0
  and co.tenant_code = #{tenantCode}
  and co.order_no = #{orderNo}

select * from customer_order co
where co.tenant_code = #{tenantCode}
  and co.customer_code = #{customerCode}
  and co.order_no in

      #{orderNo}

  and co.is_delete = 0

select * from customer_order co
where co.is_delete = 0

  and co.order_no = #{orderNo}


  and co.application_no = #{applicationNo}


  and co.project_no = #{projectNo}


  and co.customer_code = #{customerCode}


    and co.customer_name like concat(#{customerName}, '%')


    and co.transaction_type = #{transactionType}


    and co.sub_type = #{transactionSubType}


    and co.sub_mode = #{transactionSubMode}


    and co.channel = #{channel}


    and co.status = #{status}


    and co.payer_account_no = #{payerAccountNo}


    and co.payer_account_name = #{remarkCode}


    and co.remark_code = #{remarkCode}


    and co.order_time >= #{orderStartTime}


    and co.order_time < #{orderEndTime}


    and co.finish_time >= #{finishStartTime}


    and co.finish_time < #{finishEndTime}

order by co.order_time desc,id desc

select
    ifnull(sum(co.pay_amount), 0) as 'payAmount',
    ifnull(sum(co.transaction_amount), 0) as 'transactionAmount',
    ifnull(sum(co.recharge_amount), 0) as 'rechargeAmount',
    ifnull(sum(co.settle_amount), 0) as 'settleAmount',
    ifnull(sum(co.discount_amount), 0) as 'discountAmount',
    ifnull(sum(co.platform_fee), 0) as 'platformFee',
    ifnull(sum(co.channel_fee), 0) as 'channelFee',
    ifnull(sum(co.advance_fee), 0) as 'advanceFee',
    ifnull(sum(co.earn_fee), 0) as 'earnFee',
    ifnull(sum(co.taxation_amount), 0) as 'taxationAmount'
from customer_order co
where co.is_delete = 0

    and co.order_no = #{orderNo}


    and co.application_no = #{applicationNo}


    and co.project_no = #{projectNo}


    and co.customer_code = #{customerCode}


    and co.customer_name like concat(#{customerName}, '%')


    and co.transaction_type = #{transactionType}


    and co.sub_type = #{transactionSubType}


    and co.sub_mode = #{transactionSubMode}


    and co.channel = #{channel}


    and co.status = #{status}


    and co.payer_account_no = #{payerAccountNo}


    and co.payer_account_name = #{remarkCode}


    and co.remark_code = #{remarkCode}


    and co.order_time >= #{orderStartTime}


    and co.order_time < #{orderEndTime}


    and co.finish_time >= #{finishStartTime}


    and co.finish_time < #{finishEndTime}

order by co.order_time desc,id desc

SELECT
co.`customer_code`,
co.`order_no` AS 'bizSerialNo',
co.`pay_amount` AS 'orderAmount',
co.`transaction_amount`,
co.`platform_fee`,
co.`channel_fee`
FROM
customer_order co
where co.is_delete = 0


    and co.tenant_code = #{tenantCode}



    and co.transaction_mode = #{transactionMode}



    and co.channel = #{channel}


    and co.status = #{status}



    and co.order_time >= #{orderStartTime}


    and co.order_time < #{orderEndTime}

select * from customer_order where is_delete=0 and is_cancel=0 and source_order_no=#{originOrderNo}
                               and sub_type=#{subType}
and status in

    #{status}

SELECT o.*
FROM customer_order o
WHERE o.is_delete = 0
  AND o.is_cancel = 0
  AND o.project_no = #{projectNo}
  AND o.create_time BETWEEN #{dayStart} AND #{dayEnd}
  AND (o.transaction_type IS NULL OR o.transaction_type <> 3) 

    AND o.order_no IN

        #{orderNo}


  AND o.id > #{startId}
  AND NOT EXISTS (
      SELECT 1
      FROM replace_battery_device_flow f
      WHERE f.order_no = o.order_no
        AND f.is_delete = 0
  )
ORDER BY o.id
LIMIT #{pageSize}

SELECT DISTINCT r.id, r.order_no FROM customer_order r JOIN replace_battery_device_flow f ON f.order_no = r.source_order_no AND f.is_delete = 0 WHERE r.is_delete = 0 AND r.is_cancel = 0 AND r.sub_type = 3001 AND r.status = 4 AND r.create_time BETWEEN #{dayStart} AND #{dayEnd}
AND EXISTS ( SELECT 1 FROM customer_order p WHERE p.order_no = r.source_order_no AND p.is_delete = 0 AND p.is_cancel = 0 )
AND r.source_order_no IN
#{orderNo}
AND r.id > #{startId} AND f.flow_status >= 40 AND f.flow_status <> 60 AND (f.refund_order_no IS NULL OR FIND_IN_SET(r.order_no, f.refund_order_no) = 0) ORDER BY r.id LIMIT #{pageSize}

SELECT DISTINCT co.biz_no AS payNo, co.status, co.order_no, co.open_id AS openId, co.sub_type AS payType, co.pay_amount AS applyAmount, co.transaction_amount AS transactionAmount, -- 支付相关金额 COALESCE(( SELECT SUM(amount) FROM customer_order_detail WHERE order_no = co.order_no AND subject_no = '202' ), 0) AS payMargin, COALESCE(( SELECT SUM(amount) FROM customer_order_detail WHERE order_no = co.order_no AND subject_no IN ('101','300') ), 0) AS payPrincipal, -- 退款相关金额（优化后） COALESCE(( SELECT SUM(cod.amount) FROM customer_order co_refund LEFT JOIN customer_order_detail cod ON co_refund.order_no = cod.order_no WHERE co_refund.source_order_no = co.order_no AND co_refund.sub_type = 3001 AND co_refund.is_delete = 0 AND co_refund.status = 4 AND cod.subject_no = '202' ), 0) AS refundMargin, COALESCE(( SELECT SUM(cod.amount) FROM customer_order co_refund LEFT JOIN customer_order_detail cod ON co_refund.order_no = cod.order_no WHERE co_refund.source_order_no = co.order_no AND co_refund.sub_type = 3001 AND co_refund.is_delete = 0 AND co_refund.status = 4 AND cod.subject_no IN ('101','300') ), 0) AS refundPrincipal, co.order_time AS payTime, -- 退款时间（取最新或最旧的退款时间） ( SELECT MAX(finish_time) FROM customer_order WHERE source_order_no = co.order_no AND sub_type = 3001 AND is_delete = 0 AND status = 4 LIMIT 1 ) AS refundTime FROM customer_order co WHERE co.is_delete = 0
and co.biz_no = #{payNo}
and co.order_no = #{orderNo}
and co.status = #{status}
and co.order_time >= #{payTimeStart}
and co.order_time < #{payTimeEnd}
and cbr.finish_time >= #{refundTimeStart}
and cbr.finish_time < #{refundTimeEnd}
